DIM Punteggi() = { 45, 78, 12, 95, 33 }
ASORT(Punteggi(), , "D")
PRINT "Migliori punteggi: "; AJOIN(Punteggi(), ", ")

DIM Citta$() = { "Milano", "Roma", "Napoli", "Torino" }
Pos = ASCAN(Citta$(), "Roma")
IF Pos >= 0 THEN PRINT "Roma trovata all'indice "; Pos

Categorie$() = { "Elettronica", "Casa", "Elettronica", "Cibo", "Casa", "Sport" }
DIM Uniche$() = AUNIQUE(Categorie$())
PRINT "Categorie ("; UBOUND(Uniche$()) + 1; "): "; AJOIN(Uniche$(), ", ")

DIM Batch() = { 3.5, 7.2, 1.8 }
DIM Normalizzato = APAD(Batch(), 5, 0.0)
PRINT "Batch normalizzato: "; AJOIN(Normalizzato, ", ")

DIM Chiavi$() = { "nome", "eta", "citta" }
DIM Valori = { "Mario Rossi", 42, "Milano" }
DIM Coppie = AZIP(Chiavi$(), Valori)
FOR I = 0 TO UBOUND(Coppie)
  PRINT Coppie(I)(0); " = "; Coppie(I)(1)
NEXT I
